div.script:
(function () {
    function applyCond(trigger) {
        var key = trigger.getAttribute('data-cond-trigger');
        var val = trigger.type === 'checkbox'
            ? (trigger.checked ? 'yes' : 'no')
            : trigger.value;
        var groups = document.querySelectorAll(
            '[data-cond-group="' + key + '"]');
        groups.forEach(function (grp) {
            var show = grp.getAttribute('data-cond-show') === val;
            grp.style.display = show ? '' : 'none';
            grp.querySelectorAll('[data-cond-required]').forEach(
                function (inp) {
                    if (show) {
                        inp.setAttribute('required', 'required');
                    } else {
                        inp.removeAttribute('required');
                        inp.value = '';
                    }
                });
        });
    }
    document.addEventListener('DOMContentLoaded', function () {
        document.querySelectorAll('[data-cond-trigger]').forEach(
            function (t) {
                applyCond(t);
                t.addEventListener('change', function () {
                    applyCond(t);
                });
            });
    });
})();

// Live, approximate estimate.
(function () {
    function money(n) { return '$' + (Number(n) || 0).toFixed(2); }
    function recalc() {
        var box = document.getElementById('event_estimate');
        if (!box) { return; }
        var d = box.dataset;
        var roomTotal = 0;
        document.querySelectorAll('input[name="venue_ids"]:checked').forEach(
            function (cb) {
                roomTotal += parseFloat(cb.getAttribute('data-room-price')) || 0;
            });
        var g = document.querySelector('[name="guest_count"]');
        var guests = g ? (parseInt(g.value) || 0) : 0;
        var b = document.querySelector('[name="num_bars"]');
        var bars = b ? (parseInt(b.value) || 0) : 0;
        var foodEl = document.querySelector('[name="food_request"]');
        var food = foodEl ? foodEl.checked : false;
        var memEl = document.querySelector('[name="is_member"]');
        var isMember = memEl ? (memEl.value === 'yes') : false;

        var perPlate = parseFloat(d.perPlate) || 0;
        var gpb = parseFloat(d.gpb) || 100;
        var bartender = parseFloat(d.bartender) || 0;
        var barPrice = parseFloat(d.bar) || 0;
        var coordPct = parseFloat(d.coordPct) || 0;
        var coordFixed = parseFloat(d.coordFixed) || 0;
        var depositPct = parseFloat(d.depositPct) || 50;
        var memberPct = parseFloat(d.memberPct) || 0;

        var catering = food ? (guests * perPlate) : 0;
        var bartenders = (bars > 0) ? (Math.ceil(guests / gpb) * bartender) : 0;
        var barFee = bars * barPrice;
        var coord = (d.coordType === 'fixed') ? coordFixed : (roomTotal * coordPct / 100);
        // Labor is an internal P and L cost, not a customer charge.
        var subtotal = roomTotal + catering + bartenders + barFee + coord;
        if (isMember) { subtotal = subtotal * (1 - memberPct / 100); }
        var reservation = subtotal * depositPct / 100;

        var et = document.getElementById('est_total');
        var ed = document.getElementById('est_deposit');
        if (et) { et.textContent = money(subtotal); }
        if (ed) { ed.textContent = money(reservation); }
    }
    document.addEventListener('DOMContentLoaded', function () {
        recalc();
        var form = document.querySelector('form[action="/event-request/submit"]');
        if (form) {
            form.addEventListener('change', recalc);
            form.addEventListener('input', recalc);
        }
    });
})();

// Block already-reserved dates on the date picker.
(function () {
    function checkDate() {
        var inp = document.querySelector('[name="event_date"]');
        if (!inp) { return; }
        var blocked = (inp.getAttribute('data-blocked') || '')
            .split(',').filter(Boolean);
        var msg = document.getElementById('date_blocked_msg');
        if (inp.value && blocked.indexOf(inp.value) !== -1) {
            if (msg) { msg.classList.remove('d-none'); }
            inp.classList.add('is-invalid');
            inp.setCustomValidity('This date is already reserved.');
        } else {
            if (msg) { msg.classList.add('d-none'); }
            inp.classList.remove('is-invalid');
            inp.setCustomValidity('');
        }
    }
    document.addEventListener('DOMContentLoaded', function () {
        var inp = document.querySelector('[name="event_date"]');
        if (inp) {
            inp.addEventListener('change', checkDate);
            inp.addEventListener('input', checkDate);
            checkDate();
        }
    });
})();
